/*
 * A245553  A Rauzy fractal sequence: trajectory of 1 under morphism 1 -> 2,3;
 *          2 -> 3; 3 -> 1.
 * https://oeis.org/A245553
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 86, u16 n <= 86, u32 n <= 86, u64 n <= 86, u128 n <= 86,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A245553: Rauzy fractal sequence generated by the morphism
   1 → 23, 2 → 3, 3 → 1.  The infinite word is built from the
   iterative rule w0 = 1, wk+1 = wk · φ(wk) where φ is the morphism.
   a(n) is the nth symbol of this infinite word (1‑based). */

#include <stdlib.h>

seq_t a(idx_t n)
{
    /* static state: growing buffer and its current length */
    static seq_t *buf = NULL;
    static size_t len = 0;   /* number of symbols stored (>=1) */
    static size_t cap = 0;   /* allocated capacity                                            */

    /* initialise the cache on first call */
    if (buf == NULL)
    {
        cap = 64;                                 /* arbitrary initial size          */
        buf = (seq_t*)malloc(cap * sizeof(seq_t));
        if (buf == NULL) return 0;                /* out of memory – fallback        */
        len = 0;
    }

    /* ensure we have at least the first symbol 1 */
    if (len == 0)
    {
        buf[0] = 1;
        len = 1;
    }

    /* grow until we cover index n (1‑based) */
    while (len < (size_t)n)
    {
        size_t old_len = len;

        /* count how many 1's are in the current word – needed for size */
        size_t ones = 0;
        for (size_t i = 0; i < old_len; ++i)
            if (buf[i] == 1) ++ones;

        /* new total length after appending φ(word) */
        size_t needed = old_len + old_len + ones;
        if (needed > cap)
        {
            size_t new_cap = cap;
            while (new_cap < needed) new_cap *= 2;
            seq_t *tmp = (seq_t*)realloc(buf, new_cap * sizeof(seq_t));
            if (tmp == NULL) return 0;      /* memory allocation failed */
            buf = tmp;
            cap = new_cap;
        }

        /* append φ(word) to the end of the buffer */
        for (size_t i = 0; i < old_len; ++i)
        {
            seq_t ch = buf[i];
            if (ch == 1)
            {
                buf[len++] = 2;
                buf[len++] = 3;
            }
            else if (ch == 2)
                buf[len++] = 3;
            else /* ch == 3 */
                buf[len++] = 1;
        }
    }

    return buf[n - 1];   /* 1‑based offset */
}
